#include "fixes/custom_map_asset_isolation/PlayerXmlInputDigest.h"
#include "fixes/custom_map_asset_isolation/PlayerStateObservationLedger.h"
#include <cstdio>
#include <cstring>
namespace xml=dluma::fixes::custom_map_asset_isolation::player_xml_input;
namespace state=dluma::fixes::custom_map_asset_isolation::playerstate;
namespace {
#define CHECK(x)do{if(!(x)){std::printf("FAIL %d: %s\n",__LINE__,#x);return false;}}while(0)
bool Read(void* fail,std::uintptr_t p,void* out,std::size_t n)noexcept{if(fail)return false;std::memcpy(out,reinterpret_cast<const void*>(p),n);return true;}
bool Input(const char* s,std::uint64_t n,xml::Digest* d){return xml::Capture(0x10000000,0x10000000+xml::kCallerReturnRva,reinterpret_cast<std::uintptr_t>(s),n,1,Read,nullptr,d);}
bool ActualBytesChangeDigest(){xml::Digest a={},b={};CHECK(Input("<level/>",8,&a)&&Input("<other/>",8,&b));CHECK(a.complete&&a.consumed_bytes==8&&a.format==xml::Format::NativeXmlCStringV1);CHECK(std::memcmp(a.sha256,b.sha256,32));return true;}
bool NativeCStringIsDistinctFromWholeFile(){char text[]={'a',0,'b',0};xml::Digest a={},b={};CHECK(Input(text,3,&a)&&Input("a",1,&b));CHECK(a.embedded_nul&&a.file_length==3&&a.consumed_bytes==1);CHECK(!std::memcmp(a.sha256,b.sha256,32));return true;}
bool QualifiedCallerAndOwnershipRequired(){xml::Digest d={};const char* s="x";CHECK(!xml::Capture(0x10000000,0x1234,reinterpret_cast<std::uintptr_t>(s),1,1,Read,nullptr,&d));CHECK(!xml::Capture(0x10000000,0x10000000+xml::kCallerReturnRva,reinterpret_cast<std::uintptr_t>(s),1,0,Read,nullptr,&d));return true;}
bool LengthAndTerminatorBounded(){xml::Digest d={};CHECK(!Input("xyz",1,&d));CHECK(!Input("x",xml::kMaximumInputBytes+1,&d));return true;}
bool FailedReadNeverPublishes(){xml::Digest d={};CHECK(!xml::Capture(0x10000000,0x10000000+xml::kCallerReturnRva,reinterpret_cast<std::uintptr_t>("x"),1,1,Read,&d,&d));CHECK(!d.complete);CHECK(Input("",0,&d)&&d.complete&&d.consumed_bytes==0);return true;}
bool GetterKeepsMultiInputIdentity(){static state::Ledger ledger={};state::Initialize(&ledger);state::DefinitionVectorRecord initial={};initial.pointer=0x1000;initial.cache_generation=7;initial.fingerprint=100;initial.definition_count=1;initial.logical_type=3;initial.maximum_level=1;initial.record_identity_complete=true;initial.inputs_complete=true;initial.input_count=2;initial.inputs[0].consumed_input_complete=true;initial.inputs[1].consumed_input_complete=true;initial.inputs[1].consumed_input_sha256[0]=9;CHECK(state::RecordDefinitionVector(&ledger,initial));state::DefinitionVectorRecord getter={};getter.pointer=initial.pointer;getter.cache_generation=7;getter.fingerprint=100;getter.definition_count=1;CHECK(state::RecordDefinitionVector(&ledger,getter));const auto& saved=ledger.definition_vectors[0];CHECK(saved.inputs_complete&&saved.input_count==2&&saved.logical_type==3&&saved.record_identity_complete&&saved.inputs[1].consumed_input_sha256[0]==9);return true;}
bool ChangedDefinitionsLoseOldInputProof(){static state::Ledger ledger={};state::Initialize(&ledger);state::DefinitionVectorRecord initial={};initial.pointer=0x1000;initial.cache_generation=7;initial.fingerprint=100;initial.definition_count=1;initial.inputs_complete=true;initial.input_count=1;CHECK(state::RecordDefinitionVector(&ledger,initial));state::DefinitionVectorRecord changed={};changed.pointer=initial.pointer;changed.cache_generation=7;changed.fingerprint=101;changed.definition_count=1;CHECK(state::RecordDefinitionVector(&ledger,changed));CHECK(!ledger.definition_vectors[0].inputs_complete&&ledger.definition_vectors[0].input_count==0);return true;}
}
int main(){bool(*tests[])()={ActualBytesChangeDigest,NativeCStringIsDistinctFromWholeFile,QualifiedCallerAndOwnershipRequired,LengthAndTerminatorBounded,FailedReadNeverPublishes,GetterKeepsMultiInputIdentity,ChangedDefinitionsLoseOldInputProof};for(unsigned i=0;i<sizeof(tests)/sizeof(tests[0]);++i){if(!tests[i]())return 1;std::printf("PASS player_xml_%u\n",i);}return 0;}
